L14_1 = "제법 냉철하네. 난 관리국의 데모고르곤이 한바탕 날뛰는 그림을 원했는데."
L13_1.m_Talk_KOREA = L14_1
L13_1.m_fTalkTime = 0.03
L14_1 = "ずいぶん冷静だな。私は管理局のデモゴルゴンが思い切り暴れる様を見たかったのだが。"
L13_1.m_Talk_JPN = L14_1
L14_1 = "You're rather tame. I wanted to see the Administration's Demogorgon go on a rampage."
