L19_1 = "USER_ADMIN_NULL_NULL"
L18_1.m_CharStrID = L19_1
L19_1 = "우릴 방해만 하지 않는다면, 필요한 것을 되찾고 순순히 돌아가겠네."
L18_1.m_Talk_KOREA = L19_1
L18_1.m_fTalkTime = 0.03
L19_1 = "私たちの邪魔さえしなければ、必要なものを取り戻して大人しく帰ると約束しよう。"
L18_1.m_Talk_JPN = L19_1
L19_1 = "If you give us your word that you won't disturb us, we'll leave as soon as we retrieve what we came here for."
L18_1.m_Talk_ENG = L19_1
L19_1 = "只要不妨礙我們，我們會取回需要的東西，然後乖乖離開怎麼樣。"
L18_1.m_Talk_TWN = L19_1
L19_1 = "只要不妨碍我们，我们会取回需要的东西，然后乖乖离开怎么样。"
L18_1.m_Talk_SCN = L19_1
L19_1 = "If you give us your word that you won't disturb us, we'll leave as soon as we retrieve what we came here for."
L18_1.m_Talk_DEU = L19_1
L19_1 = "If you give us your word that you won't disturb us, we'll leave as soon as we retrieve what we came here for."
L18_1.m_Talk_FRA = L19_1
