L20_1 = "Fu fuu. How about you stop trying to persuade me with such naive methods?"
L19_1.m_Talk_ENG = L20_1
L20_1 = "呵呵，這種天真的勸說方式還是早點放棄吧。"
L19_1.m_Talk_TWN = L20_1
L20_1 = "呵呵，这种天真的劝说方式还是早点放弃吧。"
