L27_1.m_CharStrID = L28_1
L28_1 = "제아무리 귀한 아티팩트라 해도 그 가치가 사람 목숨에 비할 바는 아닐세."
L27_1.m_Talk_KOREA = L28_1
L27_1.m_fTalkTime = 0.03
L28_1 = "いくら貴重なアーティファクトとはいえ、人命の価値には劣る。"
L27_1.m_Talk_JPN = L28_1
L28_1 = "No matter how precious an Artifact is, it's not worth as much as a person's life."
L27_1.m_Talk_ENG = L28_1
L28_1 = "再怎麼珍貴的神器，也比不上人的性命。"
L27_1.m_Talk_TWN = L28_1
L28_1 = "再怎么珍贵的神器，也比不上人的性命。"
L27_1.m_Talk_SCN = L28_1
L28_1 = "No matter how precious an Artifact is, it's not worth as much as a person's life."
L27_1.m_Talk_DEU = L28_1
