L28_1.m_CharStrID = L29_1
L29_1 = "난 희생자가 나오는 건 원치 않아. 잠시만 물러서 준다면 아티팩트는 순순히 양도하지."
L28_1.m_Talk_KOREA = L29_1
L28_1.m_fTalkTime = 0.03
L29_1 = "私は犠牲者を出したくない。しばらく目を瞑ってくれれば、アーティファクトを手放そう。"
L28_1.m_Talk_JPN = L29_1
L29_1 = "I don't want any casualties to be made here. If you step aside for now, I will hand them over."
L28_1.m_Talk_ENG = L29_1
L29_1 = "我不希望出現犧牲者。如果你能暫時撤退，到時候我會把兩個神器雙手奉上。"
L28_1.m_Talk_TWN = L29_1
L29_1 = "我不希望出现牺牲者。如果你能暂时退后，到时候我会把两个神器双手奉上。"
